<include file="Public:header"/><form id="myform" method="post" action="" enctype="multipart/form-data">    <input type="hidden" name="discover_id" value="{pigcms{$info['discover_id']}"/>    <table cellpadding="0" cellspacing="0" class="frame_form" width="100%">        <tr>            <th width="80">信息id</th>            <td>                {pigcms{$info.discover_id}            </td>        </tr>        <tr>            <th width="80">发布者</th>            <td>                {pigcms{$info.nickname}            </td>        </tr>        <tr>            <th width="80">所属类型</th>            <td>                {pigcms{$info.type_name}            </td>        </tr>        <tr>            <th width="80">收藏人数</th>            <td>                {pigcms{$info.collection_num}            </td>        </tr>        <tr>            <th width="80">内容</th>            <td>                {pigcms{$info.discover_content}            </td>        </tr>        <tr>            <th width="80">添加时间</th>            <td>                {pigcms{$info.add_time|date='Y-m-d H:i:s',###}            </td>        </tr>    </table>    <table cellpadding="0" cellspacing="0" class="frame_form" width="100%">        <tr>            <td width="100">上传的图片：</td>        </tr>        <volist name="img_list" id="vv">            <php>if($mod==0)echo "<tr>";</php>            <td><img class="view_msg" style="width:300px;" src="{pigcms{$vv}"></td>            <php>if($mod==1)echo "</tr>";</php>        </volist>    </table>    <table cellpadding="0" cellspacing="0" class="frame_form" width="100%">        <tr>            <th width="80">审核</th>            <td>                <span class="cb-enable"><label class="cb-enable selected"><span>通过</span><input name="discover_status" type="radio" value="1" checked="checked"/></label></span>                <span class="cb-disable"><label class="cb-disable"><span>拒绝</span><input name="discover_status" type="radio" value="5"/></label></span>            </td>        </tr>        <tr>            <th width="80">拒绝理由</th>            <td><input type="text" class="input fl" name="discover_refusal" id="discover_refusal" size="25" placeholder="拒绝请填写理由" tips="拒绝时候必填"/></td>        </tr>    </table>    <div class="btn hidden">        <input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />        <input type="reset" value="取消" class="button" />    </div></form><include file="Public:footer"/>